<script setup lang="ts">import{reactive,watch}from'vue';import type{AccountInput}from'@/api/accounts';const props=defineProps<{modelValue:boolean;busy?:boolean}>();const emit=defineEmits<{'update:modelValue':[boolean];submit:[AccountInput]}>();const form=reactive<AccountInput>({username:'',displayName:'',role:'NORMAL',temporaryPassword:''});watch(()=>props.modelValue,o=>{if(o)Object.assign(form,{username:'',displayName:'',role:'NORMAL',temporaryPassword:''})});function submit(){if(form.username.trim()&&form.displayName.trim())emit('submit',{...form})}</script>
<template><el-dialog :model-value="modelValue" title="新增账号" width="480" @update:model-value="emit('update:modelValue',$event)"><el-form label-position="top"><el-form-item label="显示名称" required><el-input v-model="form.displayName"/></el-form-item><el-form-item label="登录账号" required><el-input v-model="form.username"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role" style="width:100%"><el-option label="普通用户" value="NORMAL"/><el-option label="超级管理员" value="SUPER_ADMIN"/></el-select></el-form-item><el-form-item label="临时密码（留空自动生成）"><el-input v-model="form.temporaryPassword" type="password" show-password/></el-form-item></el-form><template #footer><el-button @click="emit('update:modelValue',false)">取消</el-button><el-button type="primary" :loading="busy" @click="submit">创建</el-button></template></el-dialog></template>
